    a['p_UseMetallicGlossMap'] = bpy.props.BoolProperty(name='Use MetallicGlossMap', description='改用一张打包贴图提供金属度、高光强度、遮蔽、光滑度,可以按部位画出不同的质感;关闭则用下面三个滑条,整张材质统一一个值。\n_UseMetallicGlossMap', default=False, update=kit.writer(stack, '_UseMetallicGlossMap'))
    a['p_Metallic'] = bpy.props.FloatProperty(name='Metallic', description='金属度:0 是非金属(塑料、布、皮肤),1 是纯金属(反光带固有色、几乎没有漫反射)。用打包贴图时由贴图的 R 通道代替。\n_Metallic', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_Metallic'))
    a['p_Specular'] = bpy.props.FloatProperty(name='Specular Scale', description='高光强度的整体倍率:0 没有高光,1 是标准强度;塑料、金属想要更亮的反光可以加大,布料、皮肤保持默认或调低。用打包贴图时由贴图的 G 通道代替。\n_Specular', default=1.0, min=0.0, max=1.0, update=kit.writer(stack, '_Specular'))
