    a['p_ShadowColorBrightness'] = bpy.props.FloatProperty(name='Shadow Color Brightness', description='阴影色的明暗:阴影色 = 固有色 × 这个值。0.5 是暗一半;越小阴影越黑,越接近 1 阴影越接近固有色的亮度。\n_ShadowColorBrightness', default=0.5, min=0.0, max=1.0, update=kit.writer(stack, '_ShadowColorBrightness'))
