    a['p_AnisotropyEdgeFade'] = bpy.props.FloatProperty(name='Anisotropy Edge Fade', description='高光向头两侧的衰减:越大高光越集中在正对镜头的那一块,两侧很快消失;越小高光越向两边铺开(最小 0.01 几乎不衰减)。\n_AnisotropyEdgeFade', default=1.0, min=0.01, max=10.0, update=kit.writer(stack, '_AnisotropyEdgeFade'))
    a['p_AnisotropyRange2'] = bpy.props.FloatProperty(name='Anisotropy Range2', description='第二层高光的宽度:0 是很窄的细亮线,往 1 调亮带越来越宽越柔,往负方向越来越窄。\n_AnisotropyRange2', default=0.0, min=-1.0, max=1.0, update=kit.writer(stack, '_AnisotropyRange2'))
    a['p_AnisotropyColor2'] = bpy.props.FloatVectorProperty(name='Anisotropy Color2', description='第二层高光的颜色和强度:默认黑色 = 没有第二层高光;调成浅色(比如灰白)就会出现,颜色越亮这层越明显,实际亮度还会乘上光滑度。\n_AnisotropyColor2', size=4, subtype='COLOR_GAMMA', min=0.0, max=1.0, default=(0.0, 0.0, 0.0, 1.0,), update=kit.writer(stack, '_AnisotropyColor2'))
    a['p_StrokeScale'] = bpy.props.FloatProperty(name='Stroke Scale', description='笔触图对高光位置的影响强度:0 等于没有笔触,越大笔触图让高光错落得越厉害。\n_StrokeScale', default=1.0, update=kit.writer(stack, '_StrokeScale'))
    a['p_UseLineMap'] = bpy.props.FloatProperty(name='Use Line Map', description='线条的来源:0 = 程序按 U 方向等间距生成竖线(数量由「Line Amount」决定),1 = 改用「Line Map」贴图画出的线。\n_UseLineMap', default=0.0, update=kit.writer(stack, '_UseLineMap'))
