    a['p_LineValue'] = bpy.props.FloatProperty(name='Line Value', description='条纹带在发丝方向上的位置:0.5 居中,小于或大于 0.5 往两个方向挪,和第一层高光的「位置」是同样的含义。\n_LineValue', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_LineValue'))
    a['p_LineRange'] = bpy.props.FloatProperty(name='Line Range', description='条纹带的宽度:0 是很窄的细带,往 1 调带越来越宽,负值更窄。\n_LineRange', default=0.0, min=-1.0, max=1.0, update=kit.writer(stack, '_LineRange'))
    a['p_LineIntensity'] = bpy.props.FloatProperty(name='Line Intensity', description='线条对头发的影响强度:0 没有线条,1 线条最明显。\n_LineIntensity', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_LineIntensity'))
    a['p_LineSaturation'] = bpy.props.FloatProperty(name='Line Saturation', description='条纹带里颜色的饱和度变化:1 不变,大于 1 条纹范围内颜色更浓更艳,小于 1 更灰。\n_LineSaturation', default=1.0, min=0.0, max=10.0, update=kit.writer(stack, '_LineSaturation'))
    a['p_HairBaseTintColor'] = bpy.props.FloatVectorProperty(name='Hair Base Tint Color', description='游戏里的参数,Blender 里暂时没有对应效果,这里只记录数值,改它不会改变画面。\n_HairBaseTintColor', size=4, subtype='COLOR_GAMMA', min=0.0, max=1.0, default=(1.0, 1.0, 1.0, 1.0,), update=kit.writer(stack, '_HairBaseTintColor'))
    a['p_HairAddTintColor'] = bpy.props.FloatVectorProperty(name='Hair Add Tint Color', description='游戏里的参数,Blender 里暂时没有对应效果,这里只记录数值,改它不会改变画面。\n_HairAddTintColor', size=4, subtype='COLOR_GAMMA', min=0.0, max=1.0, default=(1.0, 1.0, 1.0, 1.0,), update=kit.writer(stack, '_HairAddTintColor'))
