    a['p_FurDyeEnable'] = bpy.props.BoolProperty(name='使用皮毛染色功能', description='皮毛染色开关:打开后用「皮毛染色」图以滤色方式叠在毛的颜色上,可以给毛画花纹或渐变色。\n_FurDyeEnable', default=False, update=kit.writer(stack, '_FurDyeEnable'))
