    a['p_FurLengthIntensity'] = bpy.props.FloatProperty(name='毛发长度', description='毛的长度:数值 × 0.01 个世界单位 = 最外层毛尖离表面的距离(默认 1 约 1 厘米);最终长度还会乘毛发方向图 A 通道的长短。\n_FurLengthIntensity', default=1.0, min=0.001, max=6.0, update=kit.writer(stack, '_FurLengthIntensity'))
