    a['p_FurCutoffEnd'] = bpy.props.FloatProperty(name='发尾CutOff', description='发尾处的裁剪阈值:噪声图低于它的地方在最外层不长毛;1 = 毛尖处只剩最亮的点(毛尖细而稀),调小则毛尖更粗更密。\n_FurCutoffEnd', default=1.0, min=0.0, max=1.0, update=kit.writer(stack, '_FurCutoffEnd'))
