    a['p_FurEdgeFade'] = bpy.props.FloatProperty(name='边缘平滑过度', description='毛在轮廓边缘的淡出:越大侧面看过去的毛越透明,毛丛的边缘越柔;0 = 不淡出,边缘最清晰。\n_FurEdgeFade', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_FurEdgeFade'))
