    a['p_ClearCoatNormalMode'] = bpy.props.FloatProperty(name='ClearCoat Normal', description='清漆层用哪套法线:Vertex = 用模型自己的顶点法线(清漆是一层平滑涂层,不跟随法线贴图的细小凹凸);Texture = 用法线贴图后的法线(清漆跟着底下的纹理起伏)。\n_ClearCoatNormalMode', default=0.0, update=kit.writer(stack, '_ClearCoatNormalMode'))
