    a['p_VFXFresnelFlip'] = bpy.props.BoolProperty(name='Fresnel Flip', description='翻转菲涅尔:关闭时是边缘强中间弱,打开后是中间强边缘弱。\n_VFXFresnelFlip', default=False, update=kit.writer(stack, '_VFXFresnelFlip'))
