    a['p_InParticle'] = bpy.props.BoolProperty(name='Use In Particle', description='用在粒子上:打开表示材质挂在粒子系统里,可以读粒子第二套 UV 里的自定义数据(Custom1.X、Custom1.Y)去驱动「按自定义数据」的滚动;关闭则这些自定义数据当 0,用于普通模型。\n_InParticle', default=True, update=kit.writer(stack, '_InParticle'))
