    a['p_ShadowLutTex'] = bpy.props.PointerProperty(type=bpy.types.Image, name='Shadow Color Lut', description='阴影色查找图:把 32×32×32 的颜色立方体横向摊成一张 1024×32 的长条图,横向分 32 格,格号对应固有色的 B,格内横轴对应 R、纵轴对应 G;查到的颜色就是这个固有色在阴影里的颜色,可以逐色定制阴影(比如肤色的阴影偏红)。\n_ShadowLutTex', update=kit.image_writer(stack, '_ShadowLutTex'))
    a['p_MetallicGlossMap'] = bpy.props.PointerProperty(type=bpy.types.Image, name='RGBA:Metal,Spec,Shadow,Smooth', description='质感打包贴图(非颜色数据,按线性画)。四个通道各管一件事,画法见下。\nR: 金属度:白 = 金属,黑 = 非金属。\nG: 高光强度:白 = 反光强,黑 = 几乎没有高光。\nB: 遮蔽:越黑的地方越容易显得暗(衣褶、缝隙里画深一点),白 = 不遮蔽。\nA: 光滑度:白 = 光滑,黑 = 粗糙。\n_MetallicGlossMap', update=kit.image_writer(stack, '_MetallicGlossMap'))
    a['p_DiffRampMap'] = bpy.props.PointerProperty(type=bpy.types.Image, name='Diffuse Ramp', description='漫反射色阶图(非颜色数据),只用中间那一行。横轴是受光量,最左是背光、最右是正对光;横轴上每一点的颜色是那档明暗的着色,饱和度越高给亮部染色越明显。\nA: 那一档受光量下「算作受光」的程度,越小越像阴影区;同一张图的 A 还会再按法线与镜头的夹角取一次,用来补偿面向镜头时的明暗。\n_DiffRampMap', update=kit.image_writer(stack, '_DiffRampMap'))
    a['p_SpecRampMap'] = bpy.props.PointerProperty(type=bpy.types.Image, name='Specular Ramp', description='高光色阶图(非颜色数据)。横轴是这个像素的高光强度(右边 = 高光中心最亮,左边 = 高光边缘);纵轴是表面的粗糙程度((1 − 金属度) × 粗糙度,下面 = 光滑的金属,上面 = 粗糙的非金属);读出的颜色会乘到高光色上,用来画彩色高光、分层高光或硬边高光。彩虹色模式下横轴改为视角。\n_SpecRampMap', update=kit.image_writer(stack, '_SpecRampMap'))
    a['p_SDFMask'] = bpy.props.PointerProperty(type=bpy.types.Image, name='RimMask/SDFMask/FlatSHMask', description='脸部蒙版(非颜色数据),四个通道各管一件事,画在脸的 UV 上。\nR: 边缘光蒙版:白 = 这里有皮肤边缘提亮,黑 = 没有。\nG: SDF 脸影的反蒙版:黑 = 用 SDF 图给的脸影(脸颊、鼻子这类要平滑影子的地方);白 = 改用普通法线明暗(耳朵、脖子、发际边),并且只有白色处才有高光。\nB: 边缘提亮取哪一档强度:黑 = 用「Face Rim Scale (SDF Area)」,白 = 用「Skin Rim Scale」。\nA: 游戏里「一键边缘光」在脸上出现的位置:白 = 可以出现,黑 = 不出现(只在打开 SDF 阴影时生效)。\n_SDFMask', update=kit.image_writer(stack, '_SDFMask'))
    a['p_SDFLightmap'] = bpy.props.PointerProperty(type=bpy.types.Image, name='SDF Lightmap', description='脸部阴影距离场图(非颜色数据)。主灯照脸时,按灯光转到的角度和这张图的值决定每个像素有没有进入阴影;灯在左右两侧时会自动镜像取图。\nR: R 与 G 相加得到阴影距离场的值:值越大,灯要转到越靠后这个像素才会变暗。\nG: 和 R 相加,见 R。\nB: 脸的平面法线的左右方向(0.5 = 正对前方,偏白或偏黑 = 朝左或朝右):让脸按「平整的脸」受光,鼻梁嘴唇的凹凸不会把影子打碎。\nA: 场景里点光、聚光等额外灯光照到脸上时用的阴影阈值,决定额外灯光的影子形状。\n_SDFLightmap', update=kit.image_writer(stack, '_SDFLightmap'))
    a['p_EmotionMap'] = bpy.props.PointerProperty(type=bpy.types.Image, name='Emotion Map', description='表情图集:把四个表情排成 2×2 一张图,每个表情占四分之一画面;编号 0 在左下,1 在右下,2 在左上,3 在右上。\nA: 覆盖范围:A 大的地方用表情图的颜色盖住基础颜色,A 为 0 的地方保留基础颜色;实际盖多少还要乘「Emotion Blend」。\n_EmotionMap', update=kit.image_writer(stack, '_EmotionMap'))
    a['p_HighlightMap'] = bpy.props.PointerProperty(type=bpy.types.Image, name='HighlightMap', description='脸部高光图(非颜色数据):RGB 就是叠上去的高光颜色与形状,黑色处没有高光;图会按「HighlightMap Vector」随视线方向左右上下挪动,看起来像高光在脸上滑动。\n_HighlightMap', update=kit.image_writer(stack, '_HighlightMap'))
    a['p_ClearCoatMask'] = bpy.props.PointerProperty(type=bpy.types.Image, name='ClearCoat Mask', description='清漆遮罩:只有 R 通道有用,白色处有清漆,黑色处没有。\nR: 清漆覆盖范围:1 = 完全有清漆,0 = 没有。\n_ClearCoatMask', update=kit.image_writer(stack, '_ClearCoatMask'))
    a['p_SilkStockingsMask'] = bpy.props.PointerProperty(type=bpy.types.Image, name='Aniso强度R+锐利度G 湿身光滑度B+透肉度A', description='丝袜遮罩(非颜色数据,需要打开「丝袜高级模式」):四个通道分别按部位控制丝袜的高光和浸湿表现。\nR: 高光强度:白 = 丝质高光明显,黑 = 没有。\nG: 高光锐利度(各向异性方向):0.5 灰 = 圆润,偏白或偏黑 = 朝不同方向拉长。\nB: 浸湿后的光滑度:白 = 湿了更光滑反光更集中,黑 = 保持原粗糙度。\nA: 浸湿后的透肉度:白 = 湿了透出肤色,黑 = 不透。\n_SilkStockingsMask', update=kit.image_writer(stack, '_SilkStockingsMask'))
    a['p_ParallaxTex'] = bpy.props.PointerProperty(type=bpy.types.Image, name='Parallax Tex', description='视差高度图:只有 R 通道有用,表示这一层图案的深浅,白 = 靠近表面,黑 = 深处;图案的亮度也由它决定。\nR: 高度:1 = 浮在表面,0 = 沉在最深处。\n_ParallaxTex', update=kit.image_writer(stack, '_ParallaxTex'))
    a['t_ParallaxTex'] = bpy.props.FloatVectorProperty(name='平铺', size=2, default=(1.0, 1.0), update=kit.st_writer(stack, '_ParallaxTex'))
    a['o_ParallaxTex'] = bpy.props.FloatVectorProperty(name='偏移', size=2, default=(0.0, 0.0), update=kit.st_writer(stack, '_ParallaxTex'))
    a['p_SplitNormalMap'] = bpy.props.PointerProperty(type=bpy.types.Image, name='Hair Normal Map', description='头发法线图(非颜色数据):前两个通道是漫反射法线,后两个通道是高光法线。\nR: 漫反射法线的横向分量。\nG: 漫反射法线的纵向分量。\nB: 高光法线的横向分量(只在「Split Diffuse / Specular Normal」打开时用)。\nA: 高光法线的纵向分量(同上)。\n_SplitNormalMap', update=kit.image_writer(stack, '_SplitNormalMap'))
    a['p_StrokeMap'] = bpy.props.PointerProperty(type=bpy.types.Image, name='Stroke Map(R:anisotropy G:specular offset)', description='笔触图(非颜色数据,按 UV 画在头发上):用灰度偏移每个像素的高光位置。\nR: 高光偏移:0.5 灰 = 不偏移,偏白往一个方向挪,偏黑往另一个方向挪,挪动的幅度由「Stroke Scale」放大;两层高光都跟着挪。\nG: 游戏里标作「高光偏移」,Blender 里目前没有用到这个通道。\n_StrokeMap', update=kit.image_writer(stack, '_StrokeMap'))
    a['t_StrokeMap'] = bpy.props.FloatVectorProperty(name='平铺', size=2, default=(1.0, 1.0), update=kit.st_writer(stack, '_StrokeMap'))
    a['o_StrokeMap'] = bpy.props.FloatVectorProperty(name='偏移', size=2, default=(0.0, 0.0), update=kit.st_writer(stack, '_StrokeMap'))
    a['p_LineMap'] = bpy.props.PointerProperty(type=bpy.types.Image, name='Line Map', description='线条图(非颜色数据),只在「Use Line Map」打开时用:读 R 通道,用来按 UV 画出线条的位置和疏密。\nR: 线条:数值越大,这一处受条纹带的影响越强。\n_LineMap', update=kit.image_writer(stack, '_LineMap'))
    a['t_LineMap'] = bpy.props.FloatVectorProperty(name='平铺', size=2, default=(1.0, 1.0), update=kit.st_writer(stack, '_LineMap'))
    a['o_LineMap'] = bpy.props.FloatVectorProperty(name='偏移', size=2, default=(0.0, 0.0), update=kit.st_writer(stack, '_LineMap'))
    a['p_MatcapTex'] = bpy.props.PointerProperty(type=bpy.types.Image, name='Matcap', description='Matcap 反光图:一张圆形的球面反光图,图的中心对应正对镜头的方向;眼珠按它被什么角度照亮来取色。RGB 与 A 的用法不同,见下。\nR: R、G、B 三个通道是不染色的反光,强度由「Matcap Color」的 A 控制。\nG: 和 R 同。\nB: 和 R 同。\nA: A 是会被「Matcap Color」的颜色染色的反光(想要彩色眼球高光就画在 A 里)。\n_MatcapTex', update=kit.image_writer(stack, '_MatcapTex'))
    a['p_FurMap'] = bpy.props.PointerProperty(type=bpy.types.Image, name='Fur Noise', description='毛发噪声图(非颜色数据):决定每一层毛壳上哪里长毛。白的地方长,黑的地方没有;图越细碎,毛越细越密。平铺只看 X 方向,X、Y 用同一个数。\nR: 毛的分布:越亮的地方毛越容易保留到毛尖。\n_FurMap', update=kit.image_writer(stack, '_FurMap'))
