def draw_Eyebrow(kit, layout, material, p):
    root = layout
    g0 = kit.group(root, p, '基础', '基础', 0, None, True)
    if g0 is not None:
        kit.texture(g0, p, 'p_BaseMap', 'Albedo', 't_BaseMap', 'o_BaseMap')
        kit.texture(g0, p, 'p_BumpMap', 'Normal Map', None, None)
        kit.texture(g0, p, 'p_EmissionMap', 'Emission', None, None)
        kit.texture(g0, p, 'p_RMOSMap', 'RMOS Map (R=Rough G=Metal B=Occ A=Spec)', None, None)
        kit.prop(g0, p, 'p_BaseColor', 'Color')
        kit.prop(g0, p, 'p_BumpScale', 'Scale')
        kit.prop(g0, p, 'p_RoughnessIntensity', 'Roughness Intensity')
        kit.prop(g0, p, 'p_MetallicIntensity', 'Metallic Intensity')
