    g2 = kit.group(root, p, '自发光', '自发光', 0, None, True)
    if g2 is not None:
        kit.prop(g2, p, 'p_EmissionBrightness', 'Emission Brightness')
    g3 = kit.group(root, p, 'Ramp', 'Ramp', 0, None, True)
    if g3 is not None:
        kit.texture(g3, p, 'p_DiffRampMap', 'Diffuse Ramp', None, None)
        kit.prop(g3, p, 'p_UseDiffRampMap', 'Diffuse Ramp')
    g4 = kit.group(root, p, '阴影色', '阴影色', 0, None, True)
    if g4 is not None:
        kit.texture(g4, p, 'p_ShadowLutTex', 'Shadow Color Lut', None, None)
        kit.prop(g4, p, 'p_UseShadowLutTex', 'Use Shadow Color LUT Tex')
        kit.prop(g4, p, 'p_ShadowColorBrightness', 'Shadow Color Brightness')
        kit.prop(g4, p, 'p_ShadowColorSaturation', 'Shadow Color Saturation')
