def draw_Eyes(kit, layout, material, p):
    root = layout
    g0 = kit.group(root, p, 'Albedo', 'Albedo', 1, None, True)
    if g0 is not None:
        kit.prop(g0, p, 'p_BaseColor', 'Color')
        kit.texture(g0, p, 'p_BaseMap', 'Albedo', 't_BaseMap', 'o_BaseMap')
        kit.prop(g0, p, 'c_SurfaceType', 'Surface Type')
        kit.prop(g0, p, 'c_Cull', 'Render Face')
        if not (p.p_Cull == 2.0):
            kit.prop(g0, p, 'c_BackFaceNormalFlip', 'Back Face Normal Flip')
        g1 = kit.group(g0, p, 'Albedo/Shadow_Color_Input', 'Shadow Color Input', 6, None, False)
        if g1 is not None:
            kit.prop(g1, p, 'p_UseShadowLutTex', 'Use Shadow Color LUT Tex')
            if not (not p.p_UseShadowLutTex):
                kit.texture(g1, p, 'p_ShadowLutTex', 'Shadow Color Lut', None, None)
            if not (p.p_UseShadowLutTex):
                kit.prop(g1, p, 'p_ShadowColorBrightness', 'Shadow Color Brightness')
            if not (p.p_UseShadowLutTex):
                kit.prop(g1, p, 'p_ShadowColorSaturation', 'Shadow Color Saturation')
        g2 = kit.group(g0, p, 'Albedo/Avatar_System_Input', 'Avatar System Input', 6, 'p_AvatarCustomizeEnable', False)
        if g2 is not None:
            kit.prop(g2, p, 'p_EyeTintColor', 'Eye Tint Color')
    g3 = kit.group(root, p, 'PBRInput', 'PBRInput', 2, None, True)
    if g3 is not None:
        kit.prop(g3, p, 'p_UseEmission', 'Use Emission')
        if not (not p.p_UseEmission):
            kit.prop(g3, p, 'p_EmissionColor', 'Emission Color')
        if not (not p.p_UseEmission):
            kit.prop(g3, p, 'p_EmissionBrightness', 'Emission Brightness')
        if not (not p.p_UseEmission):
            kit.texture(g3, p, 'p_EmissionMap', 'Emission', None, None)
        g4 = kit.group(g3, p, 'PBRInput/Diffuse_Ramp', 'Diffuse Ramp', 4, 'p_UseDiffRampMap', False)
        if g4 is not None:
            kit.texture(g4, p, 'p_DiffRampMap', 'Diffuse Ramp', None, None)
        g5 = kit.group(g3, p, 'PBRInput/Use_Matcap', 'Use Matcap', 6, 'p_UseMatcap', False)
        if g5 is not None:
            kit.texture(g5, p, 'p_MatcapTex', 'Matcap', None, None)
            kit.prop(g5, p, 'p_MatcapNormalScale', 'Matcap Normal Scale')
            kit.prop(g5, p, 'p_MatcapColor', 'Matcap Color')
            kit.separator(g5)
            kit.prop(g5, p, 'p_ParallaxScale', 'Parallax Scale')
        g6 = kit.group(g3, p, 'PBRInput/Eye_High_Light', 'Eye High Light', 4, 'p_EyeHighLight', False)
        if g6 is not None:
            kit.prop(g6, p, 'p_EyeHighLightColor', 'High Light Color')
            kit.prop(g6, p, 'p_EyeScatteringColor', 'Scattering Color')
    u7 = kit.group(root, p, 'unimplemented', '未实现功能(仅记录值,暂无效果)', 0, None, True)
    if u7 is not None:
        kit.label(u7, 'Albedo')
        if not (p.p_SurfaceType == 0.0):
            kit.prop(u7, p, 'c_BlendMode', 'Blend Type')
        if not (p.p_SurfaceType == 0.0):
            kit.prop(u7, p, 'c_TransparentDepthWrite', 'Transparent Depth Write')
        kit.label(u7, 'UseVATMap')
        kit.prop(u7, p, 'p_UseVATMap', 'UseVATMap')
        kit.texture(u7, p, 'p_AnimationTexture', 'Animation Texture', None, None)
        kit.prop(u7, p, 'p_DebugVATFrameIndex', 'DebugVATFrame')
        kit.prop(u7, p, 'p_VATFrameIndex', 'VAT Frame Index')
        kit.label(u7, 'NPR Option')
        kit.prop(u7, p, 'c_PreZStencilRefOption', 'Draw Over Hair')
        kit.label(u7, 'Alpha Test')
        kit.prop(u7, p, 'p_EnableAlphaTest', 'Alpha Test')
        kit.prop(u7, p, 'p_AlphaClipThreshold', 'Clip Threshold')
        kit.label(u7, 'VFX Color Adjustment')
        kit.prop(u7, p, 'p_EnableVFXColorAdjustment', 'VFX Color Adjustment')
        kit.prop(u7, p, 'p_ColorAdjustmentBrightness', 'Color Adjustment Brightness')
        kit.prop(u7, p, 'p_ColorAdjustmentSaturation', 'Color Adjustment Saturation')
        kit.prop(u7, p, 'p_ColorAdjustmentContrast', 'Color Adjustment Contrast')
        kit.prop(u7, p, 'p_ColorAdjustmentColorBlend', 'Color Adjustment Color Blend')
        kit.prop(u7, p, 'p_ColorAdjustmentRimWidth', 'Color Adjustment Rim Width')
        kit.prop(u7, p, 'p_ColorAdjustmentRimIntensity', 'Color Adjustment Rim Intensity')
        kit.prop(u7, p, 'p_ColorAdjustmentRimColor', 'Color Adjustment Rim Color')
