DRAW = {
    'Eyebrow': draw_Eyebrow,
    'Eyes': draw_Eyes,
    'Face': draw_Face,
    'Fur': draw_Fur,
    'Hair': draw_Hair,
    'LiquidAg': draw_LiquidAg,
    'OverlayShadow': draw_OverlayShadow,
    'Standard': draw_Standard,
    'VFX': draw_VFX,
}


def draw(kit, layout, material, p):
    function = DRAW.get(material.get('ruri_uber_part', ''))
    if function is None:
        kit.notice(layout, 'No panel layout for part ' + repr(material.get('ruri_uber_part', '')))
        return
    function(kit, layout, material, p)
